1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;
5	import org.springframework.web.bind.annotation.RequestHeader;
6	
7	/**
8	 * First step of {@code POST /api/owners}. Reads the optional {@code Idempotency-Key} header and, when
9	 * present and already seen from a prior successful create, short-circuits the pipeline by throwing
10	 * {@link IdempotentReplayException} — handled to replay the originally created owner with 200 rather
11	 * than validating and creating a duplicate (which would otherwise be a 409 identity conflict).
12	 *
13	 * <p>Runs before any validation or duplicate check so a genuine repeat never reaches those steps. The
14	 * key (present or absent) is published for {@link RecordIdempotencyKey}, which records it against the
15	 * new owner id once the create succeeds.
16	 */
17	public class CheckIdempotencyKey {
18	
19	    public void service(
20	            @RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey,
21	            IdempotencyStore store, Out<IdempotencyKey> keyOut) throws IdempotentReplayException {
22	        keyOut.set(new IdempotencyKey(idempotencyKey));
23	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
24	            Integer existingOwnerId = store.find(idempotencyKey);
25	            if (existingOwnerId != null) {
26	                throw new IdempotentReplayException(existingOwnerId);
27	            }
28	        }
29	    }
30	}
