1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}. Rejects a create request that is missing or blank in any
13	 * required field, so an invalid body is a 400 whose {@code errors} array names each offending field.
14	 * Runs before {@link BuildOwner}, which then reads the published body via {@code @Val}.
15	 *
16	 * <p>The address is normalized in place first (see {@link AddressNormalizer}) so it is stored and
17	 * returned in normalized form, and so the required-field check rejects an address that is blank after
18	 * normalization (for example one made only of whitespace). An owner may supply its address in EITHER
19	 * form: the structured {@code addressLine1} (with an optional {@code addressLine2}), which is preferred
20	 * when present, or the flat {@code address} that stays accepted for backward compatibility. When the
21	 * structured form is present the flat {@code address} is (re)composed as the normalized
22	 * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when that
23	 * second line is present, so everything downstream reading {@code address} sees the structured value.
24	 */
25	public class ValidateOwnerFields {
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
28	            throws MissingOwnerFieldsException {
29	        // Normalize whichever address fields are supplied.
30	        if (request.getAddressLine1() != null) {
31	            request.setAddressLine1(AddressNormalizer.normalize(request.getAddressLine1()));
32	        }
33	        if (request.getAddressLine2() != null) {
34	            request.setAddressLine2(AddressNormalizer.normalize(request.getAddressLine2()));
35	        }
36	        if (request.getAddress() != null) {
37	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
38	        }
39	        // Prefer the structured fields: compose the flat address from them when addressLine1 is present.
40	        String line1 = request.getAddressLine1();
41	        if (line1 != null && !line1.isBlank()) {
42	            String line2 = request.getAddressLine2();
43	            request.setAddress(line2 != null && !line2.isBlank() ? line1 + " " + line2 : line1);
44	        }
45	        List<String> errors = new ArrayList<>();
46	        require(errors, "firstName", request.getFirstName());
47	        require(errors, "lastName", request.getLastName());
48	        require(errors, "address", request.getAddress());
49	        require(errors, "city", request.getCity());
50	        require(errors, "telephone", request.getTelephone());
51	        if (!errors.isEmpty()) {
52	            throw new MissingOwnerFieldsException(errors);
53	        }
54	        validated.set(request);
55	    }
56	
57	    private static void require(List<String> errors, String field, String value) {
58	        if (value == null || value.isBlank()) {
59	            errors.add(field);
60	        }
61	    }
62	}
