3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * Validates the owner's {@code registrationDate} WHEN SUPPLIED, so a request that omits one stays
11	 * accepted (the server defaults it in {@link ResolveRegistrationDate}). A supplied date must not be
12	 * later than the server's current date; a future date is rejected with 400 via
13	 * {@link FutureRegistrationDateException}.
14	 *
15	 * <p>Reads the body published by the preceding validate step via {@code @Val} and runs before the
16	 * date is resolved/defaulted, so a future date is a 400 rather than being masked by a later step.
17	 */
18	public class ValidateRegistrationDate {
19	
20	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
21	        LocalDate supplied = request.getRegistrationDate();
22	        if (supplied == null) {
23	            return; // optional when absent; the server defaults it later
24	        }
25	        LocalDate serverDate = LocalDate.now();
26	        if (supplied.isAfter(serverDate)) {
27	            throw new FutureRegistrationDateException(supplied, serverDate);
28	        }
29	    }
30	}
