3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the telephone of a create-owner request to E.164 form: strips spaces, dashes and brackets,
9	 * keeps a leading '+' and country code when present, otherwise assumes country code '+61' and drops a
10	 * single leading '0' from the national digits, requiring 8 to 15 digits after the '+'. Anything that
11	 * cannot form a valid E.164 number is rejected with a 400 via {@link InvalidTelephoneException}. Mutates
12	 * the validated body in place (via {@code @Val}), so the stored and returned {@code telephone} is the
13	 * E.164 string (e.g. {@code 0412 345 678} becomes {@code +61412345678}). Runs after
14	 * {@link ValidateOwnerFields} (which guarantees a non-blank telephone) and before {@link BuildOwner}.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        request.setTelephone(E164Telephone.normalize(request.getTelephone()));
20	    }
21	}
