1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Rejects a create-owner request whose city already contains 50 or more owners, responding 409 via
11	 * {@link CityAtCapacityException}. Cities are compared case-insensitively. Runs before
12	 * {@link SaveOwner}, so the count excludes the owner being created.
13	 */
14	public class EnsureCityCapacity {
15	
16	    private static final int CITY_CAPACITY = 50;
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        String city = request.getCity();
21	        int count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
24	                count++;
25	            }
26	        }
27	        if (count >= CITY_CAPACITY) {
28	            throw new CityAtCapacityException(city, count);
29	        }
30	    }
31	}
