1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Step of {@code POST /api/owners} that assigns the owner's deterministic {@code householdId}.
12	 *
13	 * <p>The identifier is the first 12 upper-case hex characters of SHA-256 over
14	 * {@code normalizedLastName + '|' + postcode} (last name trimmed, internal whitespace collapsed and
15	 * lower-cased). Because it is derived purely from the household key, every owner sharing the same
16	 * last name and postcode receives the SAME value automatically, regardless of creation order and
17	 * without scanning or back-filling other owners. An owner with no postcode has no household, so its
18	 * {@code householdId} is {@code null}.
19	 *
20	 * <p>Runs after {@link BuildOwner}, so it works on the built entity, and before
21	 * {@link EnsureUniqueIdentity}, so duplicate detection and {@link AssignHouseholdSize} see the
22	 * finalized value. Note {@code sharesHousehold} plays no part here: it only bypasses the duplicate
23	 * block downstream; the household link itself is always this computed value.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val Owner owner) {
28	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
29	    }
30	
31	    /**
32	     * The deterministic householdId for a {@code (lastName, postcode)} pair, or {@code null} when the
33	     * postcode is absent (an owner with no postcode is not part of a household).
34	     */
35	    static String householdId(String lastName, String postcode) {
36	        if (postcode == null || postcode.isBlank()) {
37	            return null;
38	        }
39	        String key = normalize(lastName) + "|" + postcode.trim();
40	        try {
41	            byte[] digest = MessageDigest.getInstance("SHA-256")
42	                    .digest(key.getBytes(StandardCharsets.UTF_8));
43	            StringBuilder sb = new StringBuilder(12);
44	            for (int i = 0; i < 6; i++) {
45	                sb.append(String.format("%02X", digest[i]));
46	            }
47	            return sb.toString();
48	        }
49	        catch (NoSuchAlgorithmException e) {
50	            throw new IllegalStateException("SHA-256 not available", e);
51	        }
52	    }
53	
54	    private static String normalize(String value) {
55	        if (value == null) {
56	            return "";
57	        }
58	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
59	    }
60	}
