1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Duplicate detection for {@code POST /api/owners}, keyed on the deterministic {@code householdId}
11	 * (see {@link AssignHousehold}). Rejects a create with 409 via {@link DuplicateIdentityException} in
12	 * either of two cases:
13	 *
14	 * <ul>
15	 * <li><b>Household duplicate</b> — an existing owner already has the same {@code householdId} (i.e.
16	 * the same last name and postcode, so it is the same household). This is bypassed when the request
17	 * sets {@code sharesHousehold}, in which case the new owner is created as a declared household
18	 * member.</li>
19	 * <li><b>Exact identity</b> — the new owner's WHOLE {@code identityKey} (see {@link IdentityKey})
20	 * equals an existing owner's, i.e. the same telephone, email and household. A truly identical record
21	 * is always a conflict, even for a declared member.</li>
22	 * </ul>
23	 *
24	 * <p>Runs after {@link AssignHousehold}, so the new owner's householdId is finalized before it is
25	 * compared, and before {@link SaveOwner}.
26	 */
27	public class EnsureUniqueIdentity {
28	
29	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
32	        String identityKey = IdentityKey.of(owner);
33	        String householdId = owner.getHouseholdId();
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
36	                continue; // the owner being created is not yet its own duplicate
37	            }
38	            if (Boolean.TRUE.equals(existing.getDeleted())) {
39	                continue; // a soft-deleted owner no longer blocks a create
40	            }
41	            if (!sharesHousehold && householdId != null
42	                    && householdId.equals(existing.getHouseholdId())) {
43	                throw new DuplicateIdentityException(householdId);
44	            }
45	            if (IdentityKey.of(existing).equals(identityKey)) {
46	                throw new DuplicateIdentityException(identityKey);
47	            }
48	        }
49	    }
50	}
51

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Step of {@code POST /api/owners} that flags a soft ("possible") duplicate. The hard-duplicate
10	 * check ({@link EnsureUniqueIdentity}) has already rejected a household or exact identity collision
11	 * with 409, so this owner is being created. This step then marks it as a possible duplicate when it
12	 * is not a hard duplicate yet still shares an existing owner's last name and postcode with a
13	 * <em>different</em> telephone.
14	 *
15	 * <p>When the request opts into the household via {@code sharesHousehold} the owner is a
16	 * <em>declared</em> household member, not a suspected one, so it is never flagged. Otherwise, when a
17	 * matching existing owner is found the new owner's {@code possibleDuplicate} is set true and
18	 * {@code possibleDuplicateOf} to that owner's id (the lowest matching id when several match);
19	 * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is null. A missing
20	 * postcode never matches, since the rule keys on last name <em>and</em> postcode. Runs after
21	 * {@link EnsureUniqueIdentity} and before {@link SaveOwner}, so the flags are persisted with the owner.
22	 */
23	public class FlagPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
26	        owner.setPossibleDuplicate(false);
27	        owner.setPossibleDuplicateOf(null);
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return; // a declared household member is not a suspected duplicate
30	        }
31	        String postcode = owner.getPostcode();
32	        if (postcode == null || postcode.isBlank()) {
33	            return;
34	        }
35	        String lastName = normalize(owner.getLastName());
36	        String telephone = owner.getTelephone();
37	        Owner match = null;
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
40	                continue; // the owner being created is not its own possible duplicate
41	            }
42	            if (Boolean.TRUE.equals(existing.getDeleted())) {
43	                continue; // a soft-deleted owner is not a possible-duplicate match
44	            }
45	            if (!normalize(existing.getLastName()).equals(lastName)) {
46	                continue;
47	            }
48	            if (!postcode.equals(existing.getPostcode())) {
49	                continue;
50	            }
51	            if (telephone != null && telephone.equals(existing.getTelephone())) {
52	                continue; // a shared telephone is a hard-duplicate concern, not a soft match
53	            }
