I now have the complete pipeline. Here is everything in pipeline order, with absolute paths and verbatim source.

---

## 0. Routing / base path

- REST endpoint files live under `src/main/resources/officefloor/rest/`, and the URL path mirrors the directory tree. The `/api` prefix is simply the `rest/api/` directory, so `rest/api/owners.POST.yml` serves `POST /api/owners`.
- Additional servlet prefix in `/home/daniel/sandbox/src/main/resources/application.properties`:
  ```
  server.servlet.context-path=/petclinic/
  ```
  So the fully-qualified route is `POST /petclinic/api/owners`.
- The DTOs are generated from `/home/daniel/sandbox/src/main/resources/openapi.yml` into `target/generated-sources/openapi/...`.

---

## 1. The endpoint YAML

`/home/daniel/sandbox/src/main/resources/officefloor/rest/api/owners.POST.yml` (verbatim):

```yaml
composition:
  authorize: "hasRole('OWNER_ADMIN')"

# Idempotent create: if this request carries an 'Idempotency-Key' already seen from a prior
# successful create, replay the originally created owner (200) instead of creating a duplicate.
# Runs first, before any validation or duplicate check, and publishes the key for recordIdempotency.
checkIdempotency:
  class: org.springframework.samples.petclinic.rest.function.owner.CheckIdempotencyKey
  next: validate

validate:
  class: org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields
  next: validatePostcode

# Validate the postcode WHEN PRESENT (optional when absent), so an out-of-range postcode
# for the city's region is a 400 before the owner is built.
validatePostcode:
  class: org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode
  next: validateRegistrationDate

# Reject a SUPPLIED registrationDate later than the server date as a 400, before the date is
# resolved/defaulted. A request that omits the date stays accepted.
validateRegistrationDate:
  class: org.springframework.samples.petclinic.rest.function.owner.ValidateRegistrationDate
  next: normalizeTelephone

normalizeTelephone:
  class: org.springframework.samples.petclinic.rest.function.owner.NormalizeOwnerTelephone
  next: normalizeEmail

normalizeEmail:
  class: org.springframework.samples.petclinic.rest.function.owner.NormalizeOwnerEmail
  next: rejectDisposableEmail

# Reject a supplied email whose domain is on the disposable-domain blocklist as a 400. Runs after
# normalizeEmail so the domain is already syntactically valid and lower-cased.
rejectDisposableEmail:
  class: org.springframework.samples.petclinic.rest.function.owner.RejectDisposableEmailDomain
  next: resolveRegistrationDate

# Resolve the effective registration date (supplied-or-default, rolled forward off weekends)
# before the daily limit, so the limit counts owners per the same adjusted business day.
resolveRegistrationDate:
  class: org.springframework.samples.petclinic.rest.function.owner.ResolveRegistrationDate
  next: ensureCityCapacity

ensureCityCapacity:
  class: org.springframework.samples.petclinic.rest.function.owner.EnsureCityCapacity
  govern: [ transaction ]
  next: ensureDailyLimit

ensureDailyLimit:
  class: org.springframework.samples.petclinic.rest.function.owner.EnsureDailyLimit
  govern: [ transaction ]
  next: build

build:
  class: org.springframework.samples.petclinic.rest.function.owner.BuildOwner
  govern: [ transaction ]
  next: assignHousehold

assignHousehold:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignHousehold
  govern: [ transaction ]
  next: ensureUniqueIdentity

# Consolidated duplicate detection: reject 409 only when the new owner's WHOLE derived identityKey
# (normalizedTelephone|email|householdId) equals an existing owner's. Runs after assignHousehold so
# the new owner's householdId is part of its key.
ensureUniqueIdentity:
  class: org.springframework.samples.petclinic.rest.function.owner.EnsureUniqueIdentity
  govern: [ transaction ]
  next: flagPossibleDuplicate

# Soft duplicate: not a hard identity collision (already rejected above), but shares an existing
# owner's last name and postcode with a different telephone. Still created; flagged with
# possibleDuplicate/possibleDuplicateOf so the response can surface the likely match.
flagPossibleDuplicate:
  class: org.springframework.samples.petclinic.rest.function.owner.FlagPossibleDuplicate
  govern: [ transaction ]
  next: assignHouseholdSize

assignHouseholdSize:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignHouseholdSize
  govern: [ transaction ]
  next: defaultRegistrationDate

defaultRegistrationDate:
  class: org.springframework.samples.petclinic.rest.function.owner.DefaultOwnerRegistrationDate
  govern: [ transaction ]
  next: assignCustomerCode

assignCustomerCode:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignCustomerCode
  govern: [ transaction ]
  next: assignNamesakeCount

assignNamesakeCount:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignNamesakeCount
  govern: [ transaction ]
  next: assignBulkSignupWarning

assignBulkSignupWarning:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignBulkSignupWarning
  govern: [ transaction ]
  next: save

save:
  class: org.springframework.samples.petclinic.rest.function.owner.SaveOwner
  govern: [ transaction ]
  next: audit

# Emit an AUDIT line for the created owner (id assigned by save) before responding.
audit:
  class: org.springframework.samples.petclinic.rest.function.owner.AuditOwnerCreated
  govern: [ transaction ]
  next: recordIdempotency

# Remember this request's Idempotency-Key -> new owner id (when a key was supplied) so a later
# repeat with the same key replays this owner instead of creating a duplicate.
recordIdempotency:
  class: org.springframework.samples.petclinic.rest.function.owner.RecordIdempotencyKey
  govern: [ transaction ]
  next: respond

respond:
  class: org.springframework.samples.petclinic.rest.function.owner.RespondWithOwnerCreated
  govern: [ transaction ]
```

Note the entry point is `checkIdempotency` (no explicit "start"; the `composition.authorize` gate runs first, then the first non-composition step). There are no `outputs:` in this YAML — flow is purely linear via `next:`; branch-outs happen through thrown escalations.

---

## 2. Pipeline step classes, in order

All under `/home/daniel/sandbox/src/main/java/org/springframework/samples/petclinic/rest/function/owner/`.

### Step 1 — CheckIdempotencyKey.java
```java
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;
import org.springframework.web.bind.annotation.RequestHeader;

public class CheckIdempotencyKey {

    public void service(
            @RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey,
            IdempotencyStore store, Out<IdempotencyKey> keyOut) throws IdempotentReplayException {
        keyOut.set(new IdempotencyKey(idempotencyKey));
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            Integer existingOwnerId = store.find(idempotencyKey);
            if (existingOwnerId != null) {
                throw new IdempotentReplayException(existingOwnerId);
            }
        }
    }
}
```
(Javadoc omitted for brevity; header injection via `@RequestHeader`, publishes `Out<IdempotencyKey>`.)

### Step 2 — ValidateOwnerFields.java
```java
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        // Normalize whichever address fields are supplied.
        if (request.getAddressLine1() != null) {
            request.setAddressLine1(AddressNormalizer.normalize(request.getAddressLine1()));
        }
        if (request.getAddressLine2() != null) {
            request.setAddressLine2(AddressNormalizer.normalize(request.getAddressLine2()));
        }
        if (request.getAddress() != null) {
            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        }
        // Prefer the structured fields: compose the flat address from them when addressLine1 is present.
        String line1 = request.getAddressLine1();
        if (line1 != null && !line1.isBlank()) {
            String line2 = request.getAddressLine2();
            request.setAddress(line2 != null && !line2.isBlank() ? line1 + " " + line2 : line1);
        }
        List<String> errors = new ArrayList<>();
        require(errors, "firstName", request.getFirstName());
        require(errors, "lastName", request.getLastName());
        require(errors, "address", request.getAddress());
        require(errors, "city", request.getCity());
        require(errors, "telephone", request.getTelephone());
        if (!errors.isEmpty()) {
            throw new MissingOwnerFieldsException(errors);
        }
        validated.set(request);
    }

    private static void require(List<String> errors, String field, String value) {
        if (value == null || value.isBlank()) {
            errors.add(field);
        }
    }
}
```
This binds the request body with `@RequestBody OwnerFieldsDto` and republishes it as `Out<OwnerFieldsDto>` for the downstream `@Val` steps.

### Step 3 — ValidateOwnerPostcode.java
```java
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.CityRegion;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

public class ValidateOwnerPostcode {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        String city = request.getCity();
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException(postcode, city, "must be exactly four digits");
        }
        int[] range = CityRegion.postcodeRange(city);
        if (range == null) {
            return; // no known region for this city; any 4-digit postcode is valid
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(postcode, city,
                    "out of range " + range[0] + "-" + range[1] + " for the city's region");
        }
    }
}
```

### Step 4 — ValidateRegistrationDate.java
```java
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

public class ValidateRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied == null) {
            return; // optional when absent; the server defaults it later
        }
        LocalDate serverDate = LocalDate.now();
        if (supplied.isAfter(serverDate)) {
            throw new FutureRegistrationDateException(supplied, serverDate);
        }
    }
}
